-- Historikal roster update. GENERATED by scripts/build-historikals.mjs --update: the 7 creatures
-- that changed since the catalogue last applied.
insert into public.badge_kinds (slug, title, blurb, art, sort, rarity, element, types, rnd, shift, hearts, moves, droppable, active)
select f[1], f[2],
       'A ' || (case f[3] when 'legendary' then 'mythic' else f[3] end) || ' ' || initcap(f[4]) || case when f[5] <> '' then '/' || initcap(f[5]) else '' end || ' Historikal.',
       'creatures/' || f[1] || '.png', f[7]::int, f[3], case f[4] when 'fire' then 'fire' when 'tide' then 'water' when 'nature' then 'grass' when 'ward' then 'rock' when 'feral' then 'rock' when 'dark' then 'dark' when 'spirit' then 'light' end,
       case when f[5] <> '' then array[f[4], f[5]] else array[f[4]] end, f[8] = '1', f[9] = '1', f[6]::int,
       (select jsonb_agg(jsonb_build_object('name', split_part(m, ':', 1), 'kind', split_part(m, ':', 2)) order by o)
          from unnest(string_to_array(f[10], ';')) with ordinality as x(m, o)),
       true, true
  from (select string_to_array(l, '|') as f from unnest(string_to_array($cat$
office-zombie|OFFICE ZOMBIE|uncommon|dark|spirit|3|1032|0|0|Shadow Claw:sword;Ether Guard:armor
goblin-bandit|GOBLIN BANDIT|rare|dark|nature|3|1037|0|0|Gloom Jab:sword;Thorn Rain:spell;Fade:armor
goblin-bard|GOBLIN BARD|rare|spirit||3|1041|0|0|Glint:sword;Halo:spell;Sanctuary:armor
clever-goblin|CLEVER GOBLIN|uncommon|nature|dark|3|1051|0|0|Root Snap:sword;Gloom Wall:armor
orc-prowler|ORC PROWLER|uncommon|dark|ward|3|1095|0|0|Gloom Jab:sword;Rumble:spell
orc-raider|ORC RAIDER|uncommon|feral|nature|3|1099|0|0|Fang:sword;Pollen Burst:spell
orc-marauder|ORC MARAUDER|uncommon|feral||3|1107|0|0|Claw:sword;Musk:spell
$cat$, E'\n')) as l where btrim(l) <> '') rows
on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, art = excluded.art, sort = excluded.sort,
  rarity = excluded.rarity, element = excluded.element, types = excluded.types, rnd = excluded.rnd, shift = excluded.shift,
  hearts = excluded.hearts, moves = excluded.moves, droppable = true, active = true;
